<?php
session_start(); require_once __DIR__.'/../autenticacao.php'; require_once __DIR__.'/conexaoDB.php'; exigirLogin('gerente'); $farmaciaId=(int)$_SESSION['farmacia_id']; $inicio=$_GET['inicio']??date('Y-m-01'); $fim=$_GET['fim']??date('Y-m-d'); if(!preg_match('/^\d{4}-\d{2}-\d{2}$/',$inicio)||!preg_match('/^\d{4}-\d{2}-\d{2}$/',$fim))exit('Datas inválidas');
header('Content-Type: text/csv; charset=UTF-8'); header('Content-Disposition: attachment; filename="relatorio_'.$inicio.'_a_'.$fim.'.csv"'); echo "\xEF\xBB\xBF"; $out=fopen('php://output','w'); fputcsv($out,array('Venda','Data','Cliente','Balconista','Pagamento','Valor','Status'),';'); $stmt=mysqli_prepare($conexao,"SELECT v.*,u.nome balconista FROM vendas v INNER JOIN usuarios u ON u.id=v.usuario_id WHERE v.farmacia_id=? AND DATE(v.data_venda) BETWEEN ? AND ? ORDER BY v.data_venda"); mysqli_stmt_bind_param($stmt,'iss',$farmaciaId,$inicio,$fim); mysqli_stmt_execute($stmt); $r=mysqli_stmt_get_result($stmt); while($v=mysqli_fetch_assoc($r)){fputcsv($out,array($v['id'],$v['data_venda'],$v['cliente'],$v['balconista'],$v['forma_pagamento'],number_format($v['valor_total'],2,',','.'),$v['status']),';');} fclose($out); exit;